def binsearch(pres,i,j):
    while j-i>1:
        m=(i+j)//2
        if not pres(m): j=m
        else: i=m
    return i
def getn(A,pres,hashpres=lambda k:False):
    h=A//2
    if h>0 and not pres(h):
        # scan down up to 4 steps
        k=h
        lo=max(h-4,1)
        while k>=lo:
            if pres(k): return k
            k-=1
        return binsearch(pres,0,max(h-4,0))
    # t[h] present or h==0 : scan up
    i=h
    hi=min(h+4,A)
    k=h+1
    while k<=hi:
        if not pres(k): return k-1
        i=k; k+=1
    if i>=A:
        # array full -> hash search
        return hashsearch(A,hashpres)
    if pres(A): return hashsearch(A,hashpres)
    return binsearch(pres,i,A)
def hashsearch(A,hashpres):
    if not hashpres(A+1): return A
